# generated by tools/ail2py.py from csv_json.ail; edit the .ail until onelang s16
# Link with csv_table and json_text; field values remain strings.
def csv_json(text: str) -> str:
    cells = csv_parse(text)
    result = '['
    row = -1
    for cell in cells:
        if cell.row != row:
            if row >= 0:
                result += '],'
            result += '['
            row = cell.row
        else:
            result += ','
        result += json_quote(cell.text)
    if row >= 0:
        result += ']'
    return result + ']'
